export const MSM_BLUE_NOISE_BYTE_COUNT = 131072;
export const MSM_BLUE_NOISE_SHA256 = '53177285a348664fb8e5aab027705d6f4f45921acbf08d047046d2d099260a35';
const encodedVolume = '';
let decodedVolume;
export function copyMsmBlueNoiseVolume(destination) {
  if (destination.length !== MSM_BLUE_NOISE_BYTE_COUNT) throw new RangeError('MSM blue-noise shape mismatch');
  if (!decodedVolume) {
    const binary = atob(encodedVolume);
    decodedVolume = Uint8Array.from(binary, character => character.charCodeAt(0));
  }
  destination.set(decodedVolume);
}
